-- Synthetic training schema, not a production schema export.
CREATE TABLE equipment(code TEXT PRIMARY KEY, description TEXT, location TEXT, criticality TEXT);
INSERT INTO equipment VALUES ('PUMP-001','Cooling water pump','Utilities','High'),('MOTOR-001','Drive motor','Production','Medium'),('COMP-001','Air compressor','Utilities','High'),('VALVE-001','Control valve','Production','Low');
CREATE TABLE work_orders(id INTEGER PRIMARY KEY, equipment_code TEXT REFERENCES equipment(code), status TEXT, labor_hours REAL, cost REAL);
INSERT INTO work_orders VALUES (101,'PUMP-001','Open',3,450),(102,'MOTOR-001','Closed',5,750),(103,'COMP-001','Open',2,300),(104,'PUMP-001','Closed',4,600),(105,'VALVE-001','Closed',1,100);
CREATE TABLE stock(part TEXT, store TEXT, quantity INTEGER, reorder_level INTEGER);
INSERT INTO stock VALUES ('SEAL','MAIN',3,5),('BEARING','MAIN',12,4),('FILTER','MAIN',2,6),('SEAL','REMOTE',8,3);
-- Additional fictional relational tables. Names and columns intentionally differ from production R5 schema.
CREATE TABLE organizations(code TEXT PRIMARY KEY, name TEXT, currency TEXT);
INSERT INTO organizations VALUES ('PLANT01','Manufacturing plant','USD'),('PLANT02','Distribution plant','USD');
CREATE TABLE departments(code TEXT PRIMARY KEY, org TEXT REFERENCES organizations(code), name TEXT);
INSERT INTO departments VALUES ('MECH','PLANT01','Mechanical'),('ELEC','PLANT01','Electrical');
CREATE TABLE locations(code TEXT PRIMARY KEY, org TEXT REFERENCES organizations(code), name TEXT);
INSERT INTO locations VALUES ('UTIL','PLANT01','Utilities'),('PROD','PLANT01','Production');
CREATE TABLE equipment_links(parent TEXT, child TEXT, relationship TEXT);
INSERT INTO equipment_links VALUES ('COOL-SYS','PUMP-001','component'),('COOL-SYS','MOTOR-001','component');
CREATE TABLE trades(code TEXT PRIMARY KEY, hourly_rate REAL);
INSERT INTO trades VALUES ('MECHANICAL',50),('ELECTRICAL',60);
CREATE TABLE employees(code TEXT PRIMARY KEY, name TEXT, trade TEXT REFERENCES trades(code));
INSERT INTO employees VALUES ('E01','Training technician A','MECHANICAL'),('E02','Training technician B','ELECTRICAL');
CREATE TABLE activities(wo INTEGER REFERENCES work_orders(id), activity INTEGER, trade TEXT REFERENCES trades(code), planned_hours REAL, PRIMARY KEY(wo,activity));
INSERT INTO activities VALUES (101,10,'MECHANICAL',2),(101,20,'ELECTRICAL',1),(102,10,'ELECTRICAL',4),(104,10,'MECHANICAL',3);
CREATE TABLE labor_entries(id INTEGER PRIMARY KEY, wo INTEGER, activity INTEGER, employee TEXT REFERENCES employees(code), hours REAL, rate REAL, FOREIGN KEY(wo,activity) REFERENCES activities(wo,activity));
INSERT INTO labor_entries VALUES (1,101,10,'E01',2,50),(2,101,20,'E02',1,60),(3,102,10,'E02',5,60),(4,104,10,'E01',4,50);
CREATE TABLE parts(code TEXT PRIMARY KEY, description TEXT, unit TEXT);
INSERT INTO parts VALUES ('SEAL','Pump seal','EA'),('BEARING','Bearing','EA'),('FILTER','Filter','EA');
CREATE TABLE stores(code TEXT PRIMARY KEY, org TEXT REFERENCES organizations(code));
INSERT INTO stores VALUES ('MAIN','PLANT01'),('REMOTE','PLANT01');
CREATE TABLE bins(store TEXT REFERENCES stores(code), code TEXT, PRIMARY KEY(store,code));
INSERT INTO bins VALUES ('MAIN','A01'),('REMOTE','R01');
CREATE TABLE reservations(id INTEGER PRIMARY KEY, wo INTEGER REFERENCES work_orders(id), part TEXT REFERENCES parts(code), store TEXT REFERENCES stores(code), quantity INTEGER);
INSERT INTO reservations VALUES (1,101,'SEAL','MAIN',1),(2,103,'FILTER','MAIN',1);
CREATE TABLE material_issues(id INTEGER PRIMARY KEY, wo INTEGER REFERENCES work_orders(id), part TEXT REFERENCES parts(code), store TEXT REFERENCES stores(code), quantity INTEGER, unit_cost REAL);
INSERT INTO material_issues VALUES (1,101,'SEAL','MAIN',1,30),(2,102,'BEARING','MAIN',2,40),(3,104,'SEAL','MAIN',1,30);
CREATE TABLE suppliers(code TEXT PRIMARY KEY, name TEXT);
INSERT INTO suppliers VALUES ('SUP01','Training Supply Co'),('SUP02','Training Repair Co');
CREATE TABLE requisitions(id INTEGER PRIMARY KEY, org TEXT REFERENCES organizations(code), status TEXT);
INSERT INTO requisitions VALUES (201,'PLANT01','Approved'),(202,'PLANT01','Draft');
CREATE TABLE requisition_lines(req INTEGER REFERENCES requisitions(id), line INTEGER, part TEXT REFERENCES parts(code), quantity INTEGER, PRIMARY KEY(req,line));
INSERT INTO requisition_lines VALUES (201,1,'SEAL',5),(202,1,'FILTER',10);
CREATE TABLE purchase_orders(id INTEGER PRIMARY KEY, supplier TEXT REFERENCES suppliers(code), org TEXT REFERENCES organizations(code), status TEXT);
INSERT INTO purchase_orders VALUES (301,'SUP01','PLANT01','Approved'),(302,'SUP01','PLANT01','Closed');
CREATE TABLE purchase_lines(po INTEGER REFERENCES purchase_orders(id), line INTEGER, part TEXT REFERENCES parts(code), quantity INTEGER, unit_price REAL, PRIMARY KEY(po,line));
INSERT INTO purchase_lines VALUES (301,1,'SEAL',5,30),(302,1,'BEARING',10,40);
CREATE TABLE receipts(id INTEGER PRIMARY KEY, po INTEGER, line INTEGER, quantity INTEGER, FOREIGN KEY(po,line) REFERENCES purchase_lines(po,line));
INSERT INTO receipts VALUES (401,301,1,3),(402,302,1,10);
CREATE TABLE meters(code TEXT PRIMARY KEY, equipment TEXT REFERENCES equipment(code), unit TEXT);
INSERT INTO meters VALUES ('HOUR-C','COMP-001','Hours');
CREATE TABLE meter_readings(id INTEGER PRIMARY KEY, meter TEXT REFERENCES meters(code), reading_date TEXT, reading REAL);
INSERT INTO meter_readings VALUES (1,'HOUR-C','2026-01-01',1000),(2,'HOUR-C','2026-02-01',1250),(3,'HOUR-C','2026-03-01',1500);
CREATE TABLE pm_schedules(code TEXT PRIMARY KEY, equipment TEXT REFERENCES equipment(code), interval_value INTEGER, basis TEXT);
INSERT INTO pm_schedules VALUES ('COMP500','COMP-001',500,'Hours'),('PUMP30','PUMP-001',30,'Days');
CREATE TABLE inspections(id INTEGER PRIMARY KEY, equipment TEXT REFERENCES equipment(code), result TEXT);
INSERT INTO inspections VALUES (1,'PUMP-001','Review'),(2,'MOTOR-001','Pass');
CREATE TABLE projects(code TEXT PRIMARY KEY, name TEXT, budget REAL);
INSERT INTO projects VALUES ('SHUT01','Training shutdown',5000);
CREATE TABLE work_projects(wo INTEGER REFERENCES work_orders(id), project TEXT REFERENCES projects(code), PRIMARY KEY(wo,project));
INSERT INTO work_projects VALUES (101,'SHUT01'),(102,'SHUT01');
